using System.Net;using System.Net.Http.Headers;using System.Net.Sockets;using System.Text;using System.Text.Json;using UnifiedMediaHub.Core;using Xunit;
namespace UnifiedMediaHub.Tests;
public sealed class BridgeEndpointTests:IDisposable
{
 [Fact]public async Task RepeatedStopWaitsForTheSameRetiringImport(){var pairing=new BridgePairing(root);TaskCompletionSource entered=new(),release=new();await using var endpoint=new BridgeEndpoint(pairing,async(_p,_ct)=>{entered.TrySetResult();await release.Task;return new("unused",1);});var port=Port();endpoint.Start(port);using var client=new HttpClient(new HttpClientHandler{UseProxy=false});using var request=new HttpRequestMessage(HttpMethod.Post,$"http://127.0.0.1:{port}/bridge/v1/douyin/items"){Content=new StringContent(Body,Encoding.UTF8,"application/json")};request.Headers.Add("X-UMH-Bridge-Token",pairing.Token);var send=client.SendAsync(request);await entered.Task.WaitAsync(TimeSpan.FromSeconds(5));var first=endpoint.StopAsync();try{var second=endpoint.StopAsync();Assert.False(second.IsCompleted);}finally{release.TrySetResult();await first;try{await send;}catch(HttpRequestException){}}}
 [Fact]public async Task EndpointCanRestartOnSameExplicitPortAfterARequest(){var pairing=new BridgePairing(root);await using var endpoint=new BridgeEndpoint(pairing,(_p,_ct)=>Task.FromResult(new BridgeImportResult("unused",0)));var port=Port();using var client=new HttpClient(new HttpClientHandler{UseProxy=false});for(var run=0;run<2;run++){endpoint.Start(port);using var ping=await client.GetAsync($"http://localhost:{port}/bridge/v1/ping");Assert.Equal(HttpStatusCode.OK,ping.StatusCode);await endpoint.StopAsync();}}
 readonly string root=Path.Combine(Path.GetTempPath(),"umh-bridge-"+Guid.NewGuid().ToString("N"));
 static string Body=>"""{"bridgeVersion":"1","platform":"douyin","listKind":"liked","page":{"path":"/user/self","tab":"like"},"items":[{"hrefId":"1234567890123456789","aweme":{"awemeId":"1234567890123456789"}}]}""";
 public void Dispose(){Directory.Delete(root,true);}
 static int Port(){var l=new TcpListener(IPAddress.Loopback,0);l.Start();var port=((IPEndPoint)l.LocalEndpoint).Port;l.Stop();return port;}
 [Fact]public async Task DouyinOriginIsForbiddenEvenWithValidPairing(){var pairing=new BridgePairing(root);var imports=0;await using var endpoint=new BridgeEndpoint(pairing,(_p,_ct)=>{imports++;return Task.FromResult(new BridgeImportResult("unused",1));});var port=Port();endpoint.Start(port);using var client=new HttpClient(new HttpClientHandler{UseProxy=false});using var request=new HttpRequestMessage(HttpMethod.Post,$"http://localhost:{port}/bridge/v1/douyin/items"){Content=new StringContent(Body,Encoding.UTF8,"application/json")};request.Headers.Add("X-UMH-Bridge-Token",pairing.Token);request.Headers.Add("Origin","https://www.douyin.com");using var response=await client.SendAsync(request);Assert.Equal(HttpStatusCode.Forbidden,response.StatusCode);Assert.Contains("origin_rejected",await response.Content.ReadAsStringAsync());Assert.Equal(0,imports);}
 [Fact]public void PairingRoundTripUsesEncryptedFileAndRotationInvalidatesOld(){var pairing=new BridgePairing(root);var token=pairing.Token;Assert.Equal(43,token.Length);Assert.True(pairing.Matches(token));Assert.False(pairing.Matches(null));Assert.DoesNotContain(token,Convert.ToBase64String(File.ReadAllBytes(pairing.FilePath)));Assert.Equal(token,new BridgePairing(root).Token);pairing.Regenerate();Assert.False(pairing.Matches(token));Assert.True(pairing.Matches(new BridgePairing(root).Token));}
 [Fact]public async Task EndpointGuardsTokenOriginSizeJsonAndLifecycle(){
  var pairing=new BridgePairing(root);var imports=0;await using var endpoint=new BridgeEndpoint(pairing,(_payload,_ct)=>{imports++;return Task.FromResult(new BridgeImportResult("synthetic-job",1));});var port=Port();using var client=new HttpClient{Timeout=TimeSpan.FromSeconds(5)};
  await Assert.ThrowsAsync<HttpRequestException>(()=>client.GetAsync($"http://127.0.0.1:{port}/bridge/v1/ping"));endpoint.Start(port);Assert.True(endpoint.Enabled);
  async Task<(HttpStatusCode,string)> Send(string? token,string? origin=null,string? type="application/json",string? body=null){using var req=new HttpRequestMessage(HttpMethod.Post,$"http://127.0.0.1:{port}/bridge/v1/douyin/items");if(token!=null)req.Headers.Add("X-UMH-Bridge-Token",token);if(origin!=null)req.Headers.Add("Origin",origin);req.Content=new StringContent(body??Body,Encoding.UTF8);if(type!=null)req.Content.Headers.ContentType=MediaTypeHeaderValue.Parse(type);using var response=await client.SendAsync(req);Assert.DoesNotContain(response.Headers,h=>h.Key.StartsWith("Access-Control",StringComparison.OrdinalIgnoreCase));return(response.StatusCode,await response.Content.ReadAsStringAsync());}
  Assert.Contains("bad_token",(await Send(null)).Item2);Assert.Contains("bad_token",(await Send("wrong")).Item2);Assert.Contains("origin_rejected",(await Send(pairing.Token,"https://www.douyin.com")).Item2);Assert.Contains("invalid_payload",(await Send(pairing.Token,type:"text/plain")).Item2);Assert.Contains("too_large",(await Send(pairing.Token,body:new string('x',8*1024*1024+1))).Item2);Assert.Contains("invalid_payload",(await Send(pairing.Token,body:"{}")).Item2);
  var accepted=await Send(pairing.Token);Assert.Equal(HttpStatusCode.OK,accepted.Item1);Assert.Contains("synthetic-job",accepted.Item2);Assert.DoesNotContain(pairing.Token,accepted.Item2);Assert.Equal(1,imports);var old=pairing.Token;pairing.Regenerate();Assert.Contains("bad_token",(await Send(old)).Item2);
  using(var ping=await client.GetAsync($"http://127.0.0.1:{port}/bridge/v1/ping")){var text=await ping.Content.ReadAsStringAsync();Assert.Contains("enabled",text);Assert.DoesNotContain("job",text);}
  await endpoint.StopAsync();Assert.False(endpoint.Enabled);await Assert.ThrowsAsync<HttpRequestException>(()=>client.GetAsync($"http://127.0.0.1:{port}/bridge/v1/ping"));
 }
 [Fact]public async Task ImportIsExclusiveAndStopCancelsActiveRequest(){var pairing=new BridgePairing(root);var entered=new TaskCompletionSource();await using var endpoint=new BridgeEndpoint(pairing,async(_payload,ct)=>{entered.SetResult();await Task.Delay(Timeout.Infinite,ct);return new("unused",0);});var port=Port();endpoint.Start(port);using var client=new HttpClient();HttpRequestMessage Request(){var r=new HttpRequestMessage(HttpMethod.Post,$"http://127.0.0.1:{port}/bridge/v1/douyin/items");r.Headers.Add("X-UMH-Bridge-Token",pairing.Token);r.Content=new StringContent(Body,Encoding.UTF8,"application/json");return r;}var first=client.SendAsync(Request());await entered.Task.WaitAsync(TimeSpan.FromSeconds(5));using var second=await client.SendAsync(Request());Assert.Equal(HttpStatusCode.Conflict,second.StatusCode);Assert.Contains("busy",await second.Content.ReadAsStringAsync());await endpoint.StopAsync().WaitAsync(TimeSpan.FromSeconds(5));try{await first;}catch(HttpRequestException){}Assert.False(endpoint.Enabled);}
 [Fact]public async Task ConflictingPortDoesNotChangePort(){var pairing=new BridgePairing(root);using var occupied=new TcpListener(IPAddress.Loopback,0);occupied.Start();var port=((IPEndPoint)occupied.LocalEndpoint).Port;await using var endpoint=new BridgeEndpoint(pairing,(_p,_ct)=>Task.FromResult(new BridgeImportResult("unused",0)));Assert.Throws<SocketException>(()=>{endpoint.Start(port);});Assert.False(endpoint.Enabled);}
 [Fact]public async Task ParserRejectsSmugglingOriginAndForeignHostWithoutCors(){var pairing=new BridgePairing(root);var imports=0;await using var endpoint=new BridgeEndpoint(pairing,(_p,_ct)=>{imports++;return Task.FromResult(new BridgeImportResult("unused",1));});var port=Port();endpoint.Start(port);foreach(var headers in new[]{"Host: foreign.invalid\r\n","Host: localhost:"+port+"\r\nHost: localhost:"+port+"\r\n","Host: localhost:"+port+"\r\nTransfer-Encoding: chunked\r\n","Host: localhost:"+port+"\r\nOrigin:\r\n"}){using var socket=new TcpClient();await socket.ConnectAsync(IPAddress.Loopback,port);var stream=socket.GetStream();var raw="POST /bridge/v1/douyin/items HTTP/1.1\r\n"+headers+"X-UMH-Bridge-Token: "+pairing.Token+"\r\nContent-Type: application/json\r\nContent-Length: 2\r\n\r\n{}";await stream.WriteAsync(Encoding.ASCII.GetBytes(raw));using var reader=new StreamReader(stream);var response=await reader.ReadToEndAsync().WaitAsync(TimeSpan.FromSeconds(5));Assert.DoesNotContain("200 Result",response);Assert.DoesNotContain("Access-Control",response);Assert.DoesNotContain(pairing.Token,response);}Assert.Equal(0,imports);using var client=new HttpClient(new HttpClientHandler{UseProxy=false});using var ping=await client.GetAsync($"http://localhost:{port}/bridge/v1/ping");Assert.Equal(HttpStatusCode.OK,ping.StatusCode);}
}
